import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({ name: '', grade: 'Grade 10', subjects: 'Mathematics', phone_number: '', address: '', password: 'ST@123' });

  const fetchStudents = () => {
    axios.get('http://localhost:8081/api/view-students').then(res => setStudents(res.data));
  };

  useEffect(() => { fetchStudents(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-student', formData).then(res => {
      if(res.data.status === "Success") {
        fetchStudents();
        setShowForm(false);
        setFormData({ name: '', grade: 'Grade 10', subjects: 'Mathematics', phone_number: '', address: '', password: 'ST@123' });
        alert("✅ Student Registered Successfully!");
      }
    });
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
        <h2>🧑‍🎓 Manage Students</h2>
        <button onClick={() => setShowForm(true)} style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Register Student</button>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '12px', width: '450px' }}>
            <h3>Register New Student</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Student Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              <select value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} style={inputStyle}>
                {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026', 'A/L 2027'].map(g => <option key={g} value={g}>{g}</option>)}
              </select>
              <select value={formData.subjects} onChange={(e) => setFormData({...formData, subjects: e.target.value})} style={inputStyle}>
                {['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies'].map(s => <option key={s} value={s}>{s}</option>)}
              </select>
              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Address (Optional)" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
              <div style={{ display: 'flex', gap: '10px' }}>
                <button type="button" onClick={() => setShowForm(false)} style={{ flex: 1, padding: '10px', backgroundColor: '#cbd5e1', border: 'none', borderRadius: '8px' }}>Cancel</button>
                <button type="submit" style={{ flex: 1, padding: '10px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px' }}>Register</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
        <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
          <tr><th style={thStyle}>Full Name</th><th style={thStyle}>Grade</th><th style={thStyle}>Subject</th><th style={thStyle}>Phone</th><th style={thStyle}>Address</th></tr>
        </thead>
        <tbody>
          {students.map(s => (
            <tr key={s.id} style={{ borderBottom: '1px solid #e2e8f0' }}><td style={tdStyle}><b>{s.name}</b></td><td style={tdStyle}>{s.grade}</td><td style={tdStyle}>{s.subjects}</td><td style={tdStyle}>{s.phone_number}</td><td style={tdStyle}>{s.address || '-'}</td></tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
const inputStyle = { padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1' };
const thStyle = { padding: '12px', textAlign: 'left' };
const tdStyle = { padding: '12px' };
